551: 		return false
552: 	}
553: 	if err != nil {
554: 		// we didn't get a response which might signal a connectivity problem with
555: 		// agent - retry with agentless
556: 		return true
557: 	}
558: 	// TODO: add more status codes we do not want to retry on
559: 	doNotRetry := []int{http.StatusBadRequest, http.StatusTooManyRequests, http.StatusUnauthorized, http.StatusForbidden}
560: 	for status := range doNotRetry {
561: 		if resp.StatusCode == status {
